namespace TicketClassifier.Models;

public class TrainingResult
{
    public double MacroAccuracy { get; set; }
    public double MicroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public double LogLossReduction { get; set; }
    public string ConfusionMatrix { get; set; } = string.Empty;
    public string Message { get; set; } = string.Empty;

    /// <summary>
    /// Replace non-finite doubles (NaN, ±Infinity) with 0 so JSON serialization succeeds.
    /// </summary>
    public void Sanitize()
    {
        if (!double.IsFinite(MacroAccuracy)) MacroAccuracy = 0;
        if (!double.IsFinite(MicroAccuracy)) MicroAccuracy = 0;
        if (!double.IsFinite(LogLoss)) LogLoss = 0;
        if (!double.IsFinite(LogLossReduction)) LogLossReduction = 0;
    }
}

